// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// A bundle is one PO line with the bundle's items beneath it, and it is
// invoiced as a whole. table_po arrives either with the items nested under the
// bundle line's `children`, or as flat rows pointing back through parent_id,
// so both are read and turned into one list with each bundle's items directly
// after their bundle. table_pi is built as a tree again: the bundle is one row
// carrying its items under `children`, as the PI form hands it to PI_SAVE.
// ==========================================================================
const flattenPoLines = (lines) => {
  const rows = lines || [];

  const childrenOf = (line) => {
    const nested = Array.isArray(line.children) ? line.children : [];
    if (nested.length > 0) return nested;

    return rows.filter(
      (row) =>
        row.parent_id !== undefined &&
        row.parent_id !== null &&
        row.parent_id !== "" &&
        String(row.parent_id) === String(line.id),
    );
  };

  const claimed = new Set();

  rows.forEach((line) => {
    childrenOf(line).forEach((child) => {
      if (child && child.id !== undefined && child.id !== null) {
        claimed.add(String(child.id));
      }
    });
  });

  const flat = [];

  rows.forEach((line) => {
    if (claimed.has(String(line.id))) return;

    flat.push({ line: line, parentId: null });

    childrenOf(line).forEach((child) => {
      flat.push({ line: child, parentId: String(line.id) });
    });
  });

  return flat;
};

// What is left to invoice on a PO line, the same figure the PI form offers
// when a PO is picked there. PI_SAVE checks it again before it saves.
const remainingQty = (line) =>
  Math.max(0, toNumber(line.quantity) - toNumber(line.invoice_qty));

const exchangeRateOf = (po) => toNumber(po.exchange_rate) || 1;

const mapLineItem = (line, po, lineIndex, plantID) => {
  const invoiceQty = remainingQty(line);
  const orderQty = toNumber(line.quantity);
  const unitPrice = toNumber(line.unit_price);

  // The PO line's amounts are for its whole quantity; the invoice carries the
  // share of them that is still to be invoiced.
  const ratio = orderQty > 0 ? invoiceQty / orderQty : 0;
  let discount = toNumber(line.discount);

  if (line.discount_uom === "Amount") {
    discount = discount * ratio;
  }

  return {
    material_id: referenceId(line.item_id) || "",
    material_name: line.item_name,
    item_bundle_id: referenceId(line.item_bundle_id) || "",
    item_desc: line.item_desc || "",
