    invoice_qty: round8(invoiceQty),
    available_inv_qty: round8(invoiceQty),
    quantity_uom: referenceId(line.quantity_uom) || "",
    order_unit_price: round8(unitPrice),
    order_gross: round8(unitPrice * invoiceQty),
    order_discount: round8(discount),
    discount_uom: line.discount_uom,
    discount_amount: round8(toNumber(line.discount_amount) * ratio),
    tax_preference: referenceId(line.tax_preference) || "",
    tax_percent: line.tax_percent,
    tax_amount: round8(toNumber(line.tax_amount) * ratio),
    tax_inclusive: line.tax_inclusive,
    invoice_amount: round8(toNumber(line.po_amount) * ratio),
    line_remark_1: line.line_remark_1 || "",
    line_remark_2: line.line_remark_2 || "",
    goods_receiving_no: "",
    gr_line_id: "",
    line_gr_id: "",
    line_po_id: po.id,
    po_line_id: line.id,
    item_category_id: referenceId(line.item_category_id) || "",
    line_index: lineIndex,
    plant_id: plantID,
    tariff_id: line.tariff_id,
    payment_term_id: referenceId(po.po_payment_terms) || "",
    further_description: line.further_description || "",
    project_id: line.project_id ?? null,
    custom_fields_y78jfz24: customFields(line.custom_fields_va4w0xz3),
  };
};

// The invoice lines for one order, numbered on from `lineNumber`. A line with
// nothing left to invoice is left out, and a bundle line left out takes its
// items with it.
const buildPiLines = (po, lineNumber, plantID) => {
  const lines = [];
  const rowByPoLine = {};

  for (const entry of flattenPoLines(po.table_po)) {
    const parentRow = entry.parentId ? rowByPoLine[entry.parentId] : null;

    if (entry.parentId && !parentRow) continue;
    if (remainingQty(entry.line) <= 0) continue;

    if (parentRow) {
      if (!Array.isArray(parentRow.children)) parentRow.children = [];

      parentRow.children.push(
        mapLineItem(
          entry.line,
          po,
          `${parentRow.line_index}-${parentRow.children.length + 1}`,
          plantID,
        ),
      );
      continue;
    }

    lineNumber++;

    const row = mapLineItem(entry.line, po, lineNumber, plantID);
    lines.push(row);
    rowByPoLine[String(entry.line.id)] = row;
  }

  // A bundle is worth what its items come to, which is how the PO totals it,
  // so the bundle line's amounts are replaced by the sum of its items.
  for (const row of lines) {
    if (!Array.isArray(row.children) || row.children.length === 0) continue;

    const sumOf = (key) =>
      row.children.reduce((total, child) => total + toNumber(child[key]), 0);
    const bundleQty = toNumber(row.invoice_qty);

    row.order_gross = round8(sumOf("order_gross"));
    row.discount_amount = round8(sumOf("discount_amount"));
    row.tax_amount = round8(sumOf("tax_amount"));
    row.invoice_amount = round8(sumOf("invoice_amount"));
    row.order_unit_price = bundleQty > 0 ? round8(row.order_gross / bundleQty) : 0;
  }

  return { lines, lineNumber };
};

// Totals are counted on the top-level lines only: a bundle is counted once,
// through its bundle line.
const calculateTotals = (lines, exchangeRate) => {
  const sumOf = (key) => lines.reduce((total, line) => total + toNumber(line[key]), 0);
  const invoiceTotal = sumOf("invoice_amount");

  return {
    invoice_subtotal: round8(sumOf("order_gross")),
    invoice_total_discount: round8(sumOf("discount_amount")),
    invoice_taxes_amount: round8(sumOf("tax_amount")),
    invoice_total: round8(invoiceTotal),
    myr_total_amount: round8(invoiceTotal * exchangeRate),
  };
};

